  "pr.esiintro": "The salary slips of the month make the monthly contribution sheet for the ESIC employer portal and the challan amounts. Only employees whose pay is within the wage limit (or who were covered earlier in the same half-year) are listed in the file.",
  "pr.unver_esi": "Check before you upload: the portal's own template could not be opened when this was built (14 Nov 2026). The six columns and the reason codes follow the usual template: compare them with the sample you download from the portal (Monthly Contribution › sample file) and change this sheet if they differ.",
