  "pr.esihow": "Upload: ESIC employer portal › Monthly Contribution › choose the wage month › upload the sheet. The portal works out the shares itself; this sheet carries days and wages.",
  "pr.challan_esi": "ESI challan working",
  "pr.chnote_esi": "Due within 15 days of the end of the month. The portal makes the challan from the uploaded sheet and shows the final amount: compare it with this working.",
