  "pk.title": "Trade packs",
  "pk.intro": "Start your trade with one tap: a ready list of items with HSN or SAC and GST rate, document defaults, the App features your trade needs, and boxes on the home screen. You see everything first and can remove a pack again.",
  "pk.limit": "A pack only adds. It never deletes or changes what you already saved: an item with the same name is skipped, a setting you already filled is kept, nothing is switched off. Selling prices are left empty for you to type. Item names and notes are in English.",
