  "it.b3": "سوٗد: section 424 (پرون 234B) چھُ کمی پیٹھ پرٛتھ رٕتہٕ یا رٕتہٕ کِس حِصس 1% ییٚلہِ ٹیکسُک 90% کھوتہٕ کم دِتمُت آسہِ؛ section 425 (پرون 234C) چھُ گۄڈنِکین ترٛین قسطن ہٕنٛزِ کمی پیٹھ 3% (کانٛہہ نہٕ اگر 15 June تام 12% تہٕ 15 September تام 36% دِتمُت آسہِ) تہٕ March کِس کمی پیٹھ 1%۔",
