  "it.n_forms": "شرطہٕ چھےٚ 31 March 2026 ختم گٔمتِس ؤرِیس خٲطرٕ نوٹیفائی کٔرمتین ریٹرنن مطابق (ٹیکس پورٹلن ہٕنٛزِ رپورٹ مطابق چھِ ITR-1 تہٕ ITR-4 وۄنۍ زٕ تام مکانہٕ پراپرٹی اجازت دِوان)۔ ٹیکس ؤری 2026-27 ہٕندۍ ریٹرن چھِ وۄنۍ Income-tax Rules, 2026 تَحت نوٹیفائی گژھنۍ: فایِل کرنہٕ برونٛہہ پٔرِو فارمٕچ پَنٕنۍ لِسٹ زِ کُس ہیٚکہِ نہٕ یہِ ورتٲوِتھ۔",
