  "cv.intro": "تُہُنٛد کلائنٹ چھُ اَکہِ مُدتُک کھاتہٕ اَکِس فایِلس منٛز بند کٔرِتھ تُہہِ WhatsApp یا ای میلہِ پیٹھ سوزان۔ یِتہِ کھولِو تہٕ پٔرِو: بقایا، پارٹی، لیجر، ڈے بُک، GST حساب، فائنل اکاؤنٹس تہٕ پرٛتھ ڈاکیومنٹ۔ ژھانڈِو تہٕ فلٹر کٔرِو، کُنہِ تہِ اینٹری پیٹھ سوال پُرٛژھِو، تہٕ تبصرٕ سوٗزِو اَکِس لۄکٕٹِس فایِلس منٛز واپس۔ مفت، بغٲر لاگ اِن، تہٕ کیٛنٛہہ چھُ نہٕ اپلوڈ گژھان: فایِل چھےٚ تُہٕنٛدِس براؤزرس اَندر پرنہٕ یِوان۔",
