  "cv.how.1": "تُہُنٛد کلائنٹ چھُ Nivesh Sahayak کھولان، “میون ڈیٹا”، “پَنٕنِس اکاؤنٹنٹس سوٗزِو” منٛز گژھان تہٕ اَکِس بزنس تہٕ مُدتہِ خٲطرٕ ژارِ \"میٲنِس اکاؤنٹنٹس خٲطرٕ فایِل بنٲوِو\"۔",
