  "cv.how.4": "کھاتہٕ پٔرِو، ژھانڈِو، تہٕ کُنہِ تہِ ڈاکیومنٹ، ڈے بُک اینٹری یا اسکرینس پیٹھ دبٲوِو \"سوال یا تبصرٕ جوڑِو\"۔ یُس تُہۍ لیکھِو سُہ روزِ یَتھ براؤزرس منٛز۔",
  "cv.how.5": "کام ختم گژھنہٕ پَتہٕ کھولِو \"سوال تہٕ تبصرٕ\" تہٕ لۄکٕٹ .nsca-comments فایِل سوٗزِو واپس۔ کلائنٹ کرِ یہِ لوڈ تہٕ وُچھِ پرٛتھ سوال اینٹری نِش۔ سُہ ہیٚکہِ جواب دِتھ، تہٕ تُہۍ ہیٚکِو جواب یِتہِ لوڈ کٔرِتھ۔",
