  "cv.safe.h": "فایِلہِ منٛز کیٛاہ چھُ، تہٕ کیٛاہ نہٕ",
  "cv.safe.p": "کلائنٹ چھُ پانہٕ ٹِک کران زِ کیٛاہ گژھِ اَندر۔ عام طور چھےٚ فایِلہِ منٛز اَکِس بزنسٕکۍ اینٹری، پارٹی تہٕ آئٹم مُدتہٕ کِس اَندس تام۔ کوٹیشن تہٕ آرڈر، سیلری تہٕ اسٹاف ریکارڈ، فون نمبر تہٕ ای میل پَتہٕ، تہٕ بزنسٕچ بینک کھاتہٕ تفصیل روزن نیبر اگر کلائنٹ ٹِک کرِ نہٕ۔ تصویرٕ، PIN تہٕ بیک اَپ سیٹنگ چھِ زانٛہہ نہٕ شٲمِل۔ فایِلہِ منٛز چھُ چیکسم تاکہ کانٛہہ تبدیلی ہاوِ یَتھ پیجس پیٹھ۔ چیکسم ہیٚکہِ نہٕ تمِس روٗکِتھ یُس فایِل بدلٲوِتھ چیکسم بیٚیہِ حساب کرِ، تَوے ملٲوِو چیک کوڈ تمہِ سٕتۍ یُس کلائنٹن الگ سوزُن۔",
